            if node == v:
                return dist
            for neighbor in range(n):
                if graph[node][neighbor] and neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))
        return float('inf')

    def four_point_condition(a, b, c, d):
        ab = distance(a, b)
        ac = distance(a, c)
